import 'dart:io';
import 'package:flutter/material.dart';
import 'package:image_picker/image_picker.dart';

class MultiImagePickerExample extends StatefulWidget {
  const MultiImagePickerExample({super.key});

  @override
  State<MultiImagePickerExample> createState() => _MultiImagePickerExampleState();
}

class _MultiImagePickerExampleState extends State<MultiImagePickerExample> {
  final ImagePicker _picker = ImagePicker();

  // 선택된 이미지 리스트
  List<XFile> _selectedImages = [];

  // 최대 선택 가능 개수
  static const int _maxImages = 10;

  /// 다중 이미지 선택
  Future<void> _pickMultipleImages() async {
    try {
      final List<XFile> images = await _picker.pickMultiImage(
        maxWidth: 1024,
        maxHeight: 1024,
        imageQuality: 85,
        // limit 파라미터는 일부 플랫폼에서만 지원
      );

      if (images.isNotEmpty) {
        // 최대 개수 제한
        final newImages = images.take(_maxImages - _selectedImages.length).toList();

        setState(() {
          _selectedImages.addAll(newImages);
          // 최대 개수 초과 시 자르기
          if (_selectedImages.length > _maxImages) {
            _selectedImages = _selectedImages.take(_maxImages).toList();
          }
        });

        print('선택된 이미지: ${images.length}개');
      }
    } catch (e) {
      print('이미지 선택 에러: $e');
    }
  }

  /// 이미지 삭제
  void _removeImage(int index) {
    setState(() {
      _selectedImages.removeAt(index);
    });
  }

  /// 모든 이미지 삭제
  void _clearAll() {
    setState(() {
      _selectedImages.clear();
    });
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text('다중 이미지 선택'),
        actions: [
          if (_selectedImages.isNotEmpty)
            IconButton(
              onPressed: _clearAll,
              icon: const Icon(Icons.delete_sweep),
            ),
        ],
      ),
      body: Column(
        children: [
          // 이미지 그리드
          Expanded(
            child: _selectedImages.isEmpty
                ? const Center(
                    child: Text('이미지를 선택해주세요'),
                  )
                : GridView.builder(
                    padding: const EdgeInsets.all(8),
                    gridDelegate: const SliverGridDelegateWithFixedCrossAxisCount(
                      crossAxisCount: 3,
                      crossAxisSpacing: 8,
                      mainAxisSpacing: 8,
                    ),
                    itemCount: _selectedImages.length,
                    itemBuilder: (context, index) {
                      return Stack(
                        fit: StackFit.expand,
                        children: [
                          ClipRRect(
                            borderRadius: BorderRadius.circular(8),
                            child: Image.file(
                              File(_selectedImages[index].path),
                              fit: BoxFit.cover,
                            ),
                          ),
                          // 삭제 버튼
                          Positioned(
                            top: 4,
                            right: 4,
                            child: GestureDetector(
                              onTap: () => _removeImage(index),
                              child: Container(
                                padding: const EdgeInsets.all(4),
                                decoration: const BoxDecoration(
                                  color: Colors.black54,
                                  shape: BoxShape.circle,
                                ),
                                child: const Icon(
                                  Icons.close,
                                  size: 16,
                                  color: Colors.white,
                                ),
                              ),
                            ),
                          ),
                          // 순서 표시
                          Positioned(
                            bottom: 4,
                            left: 4,
                            child: Container(
                              padding: const EdgeInsets.symmetric(
                                horizontal: 6,
                                vertical: 2,
                              ),
                              decoration: BoxDecoration(
                                color: Colors.black54,
                                borderRadius: BorderRadius.circular(10),
                              ),
                              child: Text(
                                '${index + 1}',
                                style: const TextStyle(
                                  color: Colors.white,
                                  fontSize: 12,
                                ),
                              ),
                            ),
                          ),
                        ],
                      );
                    },
                  ),
          ),

          // 하단 버튼
          SafeArea(
            child: Padding(
              padding: const EdgeInsets.all(16),
              child: Row(
                children: [
                  Expanded(
                    child: ElevatedButton.icon(
                      onPressed: _selectedImages.length < _maxImages
                          ? _pickMultipleImages
                          : null,
                      icon: const Icon(Icons.add_photo_alternate),
                      label: Text(
                        '이미지 추가 (${_selectedImages.length}/$_maxImages)',
                      ),
                    ),
                  ),
                ],
              ),
            ),
          ),
        ],
      ),
    );
  }
}

import 'dart:io';
import 'package:flutter/foundation.dart';
