/// 미디어 선택 결과
class MediaPickResult {
  final List<XFile> files;
  final bool isCancelled;
  final String? error;

  const MediaPickResult.success(this.files)
      : isCancelled = false,
        error = null;

  const MediaPickResult.cancelled()
      : files = const [],
        isCancelled = true,
        error = null;

  const MediaPickResult.error(this.error)
      : files = const [],
        isCancelled = false;

  bool get hasFiles => files.isNotEmpty;
}

/// 미디어 타입
enum MediaType { image, video }

/// 미디어 선택 서비스
class MediaPickerService {
  final ImagePicker _picker = ImagePicker();

  // 기본 이미지 설정
  static const double defaultMaxWidth = 1920;
  static const double defaultMaxHeight = 1920;
  static const int defaultImageQuality = 85;
  static const Duration defaultMaxVideoDuration = Duration(minutes: 5);

  /// 단일 이미지 선택
  Future<MediaPickResult> pickSingleImage({
    required ImageSource source,
    double? maxWidth,
    double? maxHeight,
    int? imageQuality,
    CameraDevice preferredCamera = CameraDevice.rear,
  }) async {
    try {
      final XFile? image = await _picker.pickImage(
        source: source,
        maxWidth: maxWidth ?? defaultMaxWidth,
        maxHeight: maxHeight ?? defaultMaxHeight,
        imageQuality: imageQuality ?? defaultImageQuality,
        preferredCameraDevice: preferredCamera,
      );

      if (image == null) {
        return const MediaPickResult.cancelled();
      }

      return MediaPickResult.success([image]);
    } catch (e) {
      debugPrint('이미지 선택 에러: $e');
      return MediaPickResult.error(e.toString());
    }
  }

  /// 다중 이미지 선택
  Future<MediaPickResult> pickMultipleImages({
    int? limit,
    double? maxWidth,
    double? maxHeight,
    int? imageQuality,
  }) async {
    try {
      final List<XFile> images = await _picker.pickMultiImage(
        maxWidth: maxWidth ?? defaultMaxWidth,
        maxHeight: maxHeight ?? defaultMaxHeight,
        imageQuality: imageQuality ?? defaultImageQuality,
        limit: limit,
      );

      if (images.isEmpty) {
        return const MediaPickResult.cancelled();
      }

      return MediaPickResult.success(images);
    } catch (e) {
      debugPrint('다중 이미지 선택 에러: $e');
      return MediaPickResult.error(e.toString());
    }
  }

  /// 동영상 선택
  Future<MediaPickResult> pickVideo({
    required ImageSource source,
    Duration? maxDuration,
    CameraDevice preferredCamera = CameraDevice.rear,
  }) async {
    try {
      final XFile? video = await _picker.pickVideo(
        source: source,
        maxDuration: maxDuration ?? defaultMaxVideoDuration,
        preferredCameraDevice: preferredCamera,
      );

      if (video == null) {
        return const MediaPickResult.cancelled();
      }

      return MediaPickResult.success([video]);
    } catch (e) {
      debugPrint('동영상 선택 에러: $e');
      return MediaPickResult.error(e.toString());
    }
  }

  /// 파일 크기 확인 (바이트)
  Future<int> getFileSize(XFile file) async {
    if (kIsWeb) {
      final bytes = await file.readAsBytes();
      return bytes.length;
    } else {
      final fileInfo = File(file.path);
      return await fileInfo.length();
    }
  }

  /// 파일 크기 포맷팅
  String formatFileSize(int bytes) {
    if (bytes < 1024) return '$bytes B';
    if (bytes < 1024 * 1024) return '${(bytes / 1024).toStringAsFixed(1)} KB';
    return '${(bytes / (1024 * 1024)).toStringAsFixed(1)} MB';
  }

  /// 이미지/동영상 선택 바텀시트 표시
  static Future<ImageSource?> showSourcePicker(context) async {
    return await showModalBottomSheet<ImageSource>(
      context: context,
      builder: (context) => SafeArea(
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            ListTile(
              leading: const Icon(Icons.photo_library),
              title: const Text('갤러리에서 선택'),
              onTap: () => Navigator.pop(context, ImageSource.gallery),
            ),
            ListTile(
              leading: const Icon(Icons.camera_alt),
              title: const Text('카메라로 촬영'),
              onTap: () => Navigator.pop(context, ImageSource.camera),
            ),
          ],
        ),
      ),
    );
  }
}

// 사용 예시
class ExampleUsage {
  final _mediaService = MediaPickerService();

  Future<void> pickProfileImage(context) async {
    // 1. 소스 선택 (갤러리/카메라)
    final source = await MediaPickerService.showSourcePicker(context);
    if (source == null) return;

    // 2. 이미지 선택
    final result = await _mediaService.pickSingleImage(
      source: source,
      maxWidth: 512,  // 프로필은 작게
      maxHeight: 512,
      imageQuality: 80,
    );

    // 3. 결과 처리
    if (result.hasFiles) {
      final file = result.files.first;
      final size = await _mediaService.getFileSize(file);
      print('선택된 파일: ${file.name}');
      print('파일 크기: ${_mediaService.formatFileSize(size)}');
    } else if (result.error != null) {
      print('에러: ${result.error}');
    }
  }
}

import 'dart:typed_data';
import 'package:flutter/foundation.dart';
import 'package:image_picker/image_picker.dart';
import 'package:http/http.dart' as http;

/// 크로스 플랫폼 이미지 업로드 유틸리티
class ImageUploadUtil {

  /// XFile을 Uint8List(바이트)로 변환
  /// Web과 Mobile 모두에서 동작
  static Future<Uint8List> fileToBytes(XFile file) async {
    return await file.readAsBytes();
  }

  /// 이미지 업로드 (Multipart)
  static Future<String?> uploadImage({
    required XFile file,
    required String uploadUrl,
    String fieldName = 'image',
    Map<String, String>? headers,
    Map<String, String>? additionalFields,
  }) async {
    try {
      // Multipart request 생성
      final request = http.MultipartRequest('POST', Uri.parse(uploadUrl));

      // 헤더 추가
      if (headers != null) {
        request.headers.addAll(headers);
      }

      // 추가 필드
      if (additionalFields != null) {
        request.fields.addAll(additionalFields);
      }

      // 파일 추가 (Web/Mobile 호환)
      if (kIsWeb) {
        // Web: 바이트로 읽어서 추가
        final bytes = await file.readAsBytes();
        request.files.add(
          http.MultipartFile.fromBytes(
            fieldName,
            bytes,
            filename: file.name,
          ),
        );
      } else {
        // Mobile: 파일 경로로 추가
        request.files.add(
          await http.MultipartFile.fromPath(
            fieldName,
            file.path,
            filename: file.name,
          ),
        );
      }

      // 요청 전송
      final streamedResponse = await request.send();
      final response = await http.Response.fromStream(streamedResponse);

      if (response.statusCode == 200 || response.statusCode == 201) {
        return response.body; // 성공: 응답 본문 반환
      } else {
        debugPrint('업로드 실패: ${response.statusCode}');
        return null;
      }
    } catch (e) {
      debugPrint('업로드 에러: $e');
      return null;
    }
  }

  /// 다중 이미지 업로드
  static Future<List<String>> uploadMultipleImages({
    required List<XFile> files,
    required String uploadUrl,
    String fieldName = 'images',
    void Function(int current, int total)? onProgress,
  }) async {
    final results = <String>[];

    for (int i = 0; i < files.length; i++) {
      onProgress?.call(i + 1, files.length);

      final result = await uploadImage(
        file: files[i],
        uploadUrl: uploadUrl,
        fieldName: '$fieldName[$i]',
      );

      if (result != null) {
        results.add(result);
      }
    }

    return results;
  }
}

